import type { PricingData } from "@/calculator/lib/data.ts";
import data from "@/calculator/output/pricing-data.json";

/** Built-in price lists, generated by `npm.cmd run catalog`. */
export const basePricingData = data as PricingData;

export function shortName(name: string): string {
  return name.replace(/ (Industries|Gutter Systems|Supply|Inc\.?)$/, "");
}

export function daysOld(date: string, today = new Date()): number {
  return Math.floor((today.getTime() - new Date(`${date}T00:00:00`).getTime()) / 86_400_000);
}

export function formatMoney(value: number): string {
  return value.toLocaleString("en-US", { style: "currency", currency: "USD" });
}

export function downloadFile(name: string, content: string, type: string) {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const link = document.createElement("a");
  link.href = url;
  link.download = name;
  link.click();
  URL.revokeObjectURL(url);
}
